{"exit_code": 0, "stdout_tail": "def fit(df, formula, est):
    kw = {}
    cl = est.get("cluster")
    if cl:
        kw = dict(cov_type="cluster", cov_kwds={"groups": df[cl]})
    else:
        kw = dict(cov_type=est.get("robust") or "HC2")
    w = est.get("weights")
    model = smf.wls(formula, data=df, weights=df[w]) if w else smf.ols(formula, data=df)
    return model.fit(**kw)

def build_formula(y, est, covs, d, arm_term="treat"):
    kind = est.get("kind", "ols")
    fe = "".join(f" + C({c})" for c in (est.get("absorb") or []))      # fixed effects
    cats = cat_set(est)
    if kind == "did":
        # difference in differences: the treat x post interaction is the estimate
        return f"{y} ~ {arm_term} * post" + "".join(f" + {term(c, cats)}" for c in covs) + fe, d
    if kind == "diff_means" or not covs:
        return f"{y} ~ {arm_term}" + fe, d
    if kind == "lin":
